class BowlingGame:
    def __init__(self):
        self._rolls = []
        self._frames = []

    def roll(self, pins):
        if not 0 <= pins <= 10:
            raise Exception("Roll must be between 0 and 10 pins")
        if self._game_complete():
            raise Exception("Cannot roll after game is over")

        is_tenth = len(self._frames) == 10
        frame = self._frames[-1] if self._frames else None
        if frame is None or self._frame_complete(frame, is_tenth):
            self._frames.append([pins])
            self._rolls.append(pins)
            return

        if len(frame) == 1:
            first = frame[0]
            if first == 10:
                # Strike in the tenth frame: first bonus roll.
                frame.append(pins)
            else:
                if pins > 10 - first:
                    raise Exception("Frame cannot score more than 10 pins")
                frame.append(pins)
            self._rolls.append(pins)
            return

        # Two rolls already in the frame: only possible in the tenth frame,
        # and only after a strike. This is the second bonus roll.
        second = frame[1]
        if second != 10 and pins > 10 - second:
            raise Exception("Bonus roll cannot score more than 10 pins")
        frame.append(pins)
        self._rolls.append(pins)

    def score(self):
        if not self._game_complete():
            raise Exception("Cannot score an incomplete game")

        total = 0
        idx = 0
        for frame_num, frame in enumerate(self._frames):
            if frame_num == 9:
                total += sum(frame)
            elif frame[0] == 10:
                total += 10 + self._rolls[idx + 1] + self._rolls[idx + 2]
                idx += 1
            elif frame[0] + frame[1] == 10:
                total += 10 + self._rolls[idx + 2]
                idx += 2
            else:
                total += sum(frame)
                idx += 2
        return total

    def _frame_complete(self, frame, is_tenth):
        if not is_tenth:
            return len(frame) == 2 or frame[0] == 10
        if len(frame) == 3:
            return True
        if len(frame) == 2:
            return frame[0] + frame[1] < 10
        return False

    def _game_complete(self):
        if len(self._frames) < 10:
            return False
        return self._frame_complete(self._frames[-1], is_tenth=True)
